from collections import OrderedDict

def lru(maxsize):
    def deco(fn):
        cache = OrderedDict()
        @functools.wraps(fn)
        def wrapper(x):
            if x in cache:
                cache.move_to_end(x)
                return cache[x], "hit"
            result = fn(x)
            cache[x] = result
            if len(cache) > maxsize:
                evicted, _ = cache.popitem(last=False)
                return result, f"miss, evicted {evicted}"
            return result, "miss"
