class OneShot:
    def __init__(self):
        self.used = False
    def __enter__(self):
        if self.used:
            raise RuntimeError("this manager is single-use")
        self.used = True
        print("entered")
        return self
    def __exit__(self, *exc):
        print("exited")
        return False

m = OneShot()
