import functools

def counted(fn):
    @functools.wraps(fn)
    def wrapper(*a, **k):
        wrapper.calls += 1
        return fn(*a, **k)
    wrapper.calls = 0
    return wrapper

def ensure_positive(fn):
    @functools.wraps(fn)
    def wrapper(x):
        if x < 0:
            raise ValueError("negative")
        return fn(x)
    return wrapper

@counted
@ensure_positive
def double(x):
    return x * 2

print(double(21))
try:
    double(-1)
except ValueError as e:
    print("rejected:", e)
print("double was entered", double.calls, "times (including the rejected call)")

store = {"balance": 100}
commands = {}

def command(fn):
    commands[fn.__name__] = fn
    return fn

from contextlib import contextmanager

@contextmanager
def unit_of_work(store):
    snapshot = dict(store)
    try:
        yield store
    except BaseException:
        store.clear()
        store.update(snapshot)
        raise

@command
def deposit(s, amount):
    s["balance"] += amount
    return s["balance"]

@command
def withdraw(s, amount):
    if amount > s["balance"]:
        raise ValueError("insufficient funds")
    s["balance"] -= amount
    return s["balance"]

with unit_of_work(store) as s:
    print("deposit:", commands["deposit"](s, 50))
    print("withdraw:", commands["withdraw"](s, 30))
print("committed balance:", store["balance"])

try:
    with unit_of_work(store) as s:
        print("deposit:", commands["deposit"](s, 10))
        commands["withdraw"](s, 999)
except ValueError as e:
    print("suite failed:", e)
print("balance after rollback:", store["balance"])
